package io.invenlio.sales;
import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.*;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers@SpringBootTest@AutoConfigureMockMvc@ActiveProfiles("test")class SalesIntegrationTest{static final UUID T=UUID.fromString("a1111111-1111-4111-8111-111111111111"),P=UUID.randomUUID(),V=UUID.randomUUID(),W=UUID.randomUUID(),Z=UUID.randomUUID(),L=UUID.randomUUID();@Container@ServiceConnection static final PostgreSQLContainer DB=new PostgreSQLContainer("postgres:17.6-alpine");@Autowired JdbcTemplate db;@Autowired MockMvc mvc;
 @BeforeEach void seed(){UUID u=UUID.randomUUID(),m=UUID.randomUUID(),r=UUID.randomUUID();db.update("INSERT INTO organizations(id,name,slug,status,default_locale,default_timezone,default_currency,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','en','UTC','EUR',now(),now(),0)",T,"Sales Tenant","sales-tenant");db.update("INSERT INTO user_identities(id,keycloak_subject,status,created_at,updated_at)VALUES(?,?,'ACTIVE',now(),now())",u,"seller");db.update("INSERT INTO organization_memberships(id,tenant_id,user_identity_id,status,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE',now(),now(),0)",m,T,u);db.update("INSERT INTO roles(id,tenant_id,name,system_role,created_at,updated_at,version)VALUES(?,?,?,false,now(),now(),0)",r,T,"SALES TEST");for(String x:List.of("customer:read","customer:manage","sales-order:read","sales-order:manage","sales-order:allocate","inventory:adjust"))db.update("INSERT INTO role_permissions VALUES(?,?,?)",T,r,x);db.update("INSERT INTO membership_roles VALUES(?,?,?)",T,m,r);db.update("INSERT INTO catalog_products(id,tenant_id,name,status,base_unit,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','EA',now(),now(),0)",P,T,"Widget");db.update("INSERT INTO catalog_product_variants(id,tenant_id,product_id,sku,normalized_sku,status,display_name,base_unit,option_signature,created_at,updated_at,version)VALUES(?,?,?,?,?,'ACTIVE','Widget Blue','EA','DEFAULT',now(),now(),0)",V,T,P,"SKU-1","SKU-1");db.update("INSERT INTO warehouses(id,tenant_id,code,normalized_code,name,status,timezone,created_at,updated_at,version)VALUES(?,?, 'WH-1','WH-1','Main','ACTIVE','UTC',now(),now(),0)",W,T);db.update("INSERT INTO warehouse_zones(id,tenant_id,warehouse_id,code,normalized_code,name,type,status,created_at,updated_at,version)VALUES(?,?,?,'ST','ST','Storage','STORAGE','ACTIVE',now(),now(),0)",Z,T,W);db.update("INSERT INTO warehouse_locations(id,tenant_id,warehouse_id,zone_id,code,normalized_code,type,status,scan_code,normalized_scan_code,sequence,created_at,updated_at,version)VALUES(?,?,?,?,'BIN-1','BIN-1','BIN','ACTIVE','BIN-1','BIN-1',1,now(),now(),0)",L,T,W,Z);}
 @AfterEach void clean(){db.execute("TRUNCATE sales_allocations,sales_order_lines,sales_orders,sales_order_number_counters,customers,customer_number_counters,inventory_reservation_allocations,inventory_reservations,inventory_ledger_entries,inventory_movements,inventory_balances,inventory_serials,inventory_lots CASCADE");db.update("DELETE FROM warehouse_locations WHERE tenant_id=?",T);db.update("DELETE FROM warehouse_zones WHERE tenant_id=?",T);db.update("DELETE FROM warehouses WHERE tenant_id=?",T);db.update("DELETE FROM catalog_product_variants WHERE tenant_id=?",T);db.update("DELETE FROM catalog_products WHERE tenant_id=?",T);db.update("DELETE FROM audit_events WHERE tenant_id=?",T);db.update("DELETE FROM membership_roles WHERE tenant_id=?",T);db.update("DELETE FROM role_permissions WHERE tenant_id=?",T);db.update("DELETE FROM organization_memberships WHERE tenant_id=?",T);db.update("DELETE FROM roles WHERE tenant_id=?",T);db.update("DELETE FROM user_identities WHERE keycloak_subject='seller'");db.update("DELETE FROM organizations WHERE id=?",T);}
 @Test void customerLifecycleNumberingFilteringAndOptimisticLocking()throws Exception{UUID c=customer(false);mvc.perform(post("/api/v1/customers/"+c+"/activate").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ACTIVE"));mvc.perform(get("/api/v1/customers?status=ACTIVE&q=acme&sort=name").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$[0].customerNumber").value(org.hamcrest.Matchers.matchesPattern("CUS-[0-9]{6}")));mvc.perform(patch("/api/v1/customers/"+c).with(token()).contentType("application/json").content(customerJson(0))).andExpect(status().isConflict());}
 @Test void confirmationValidatesLifecycleAndFreezesSnapshots()throws Exception{UUID c=customer(false),o=order(c);line(o,"2","12.50");mvc.perform(post("/api/v1/sales-orders/"+o+"/confirm").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("CUSTOMER_NOT_ACTIVE"));activate(c);mvc.perform(post("/api/v1/sales-orders/"+o+"/confirm").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isOk()).andExpect(jsonPath("$.subtotal").value(25.0)).andExpect(jsonPath("$.lines[0].sku").value("SKU-1"));db.update("UPDATE catalog_product_variants SET sku='NEW',normalized_sku='NEW',display_name='Changed' WHERE id=?",V);mvc.perform(get("/api/v1/sales-orders/"+o).with(token())).andExpect(jsonPath("$.lines[0].sku").value("SKU-1")).andExpect(jsonPath("$.lines[0].description").value("Widget Blue"));mvc.perform(post("/api/v1/sales-orders/"+o+"/lines").with(token()).contentType("application/json").content(lineJson("1","1"))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("SALES_ORDER_NOT_EDITABLE"));}
 @Test void mandatoryOutboundScenarioAllocatesPartiallyThenRetriesWithoutMovement()throws Exception{stock("opening",100);int ledger=count("inventory_ledger_entries");UUID c=activeCustomer(),first=ready(c,"80");mvc.perform(post("/api/v1/sales-orders/"+first+"/allocate").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ALLOCATED")).andExpect(jsonPath("$.lines[0].allocatedQuantity").value(80.0)).andExpect(jsonPath("$.lines[0].backorderedQuantity").value(0.0));assertBalance(100,80);assertEquals(ledger,count("inventory_ledger_entries"));UUID second=ready(c,"50");mvc.perform(post("/api/v1/sales-orders/"+second+"/allocate").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("PARTIALLY_ALLOCATED")).andExpect(jsonPath("$.lines[0].allocatedQuantity").value(20.0)).andExpect(jsonPath("$.lines[0].backorderedQuantity").value(30.0));assertBalance(100,100);stock("receipt-compatible",30);mvc.perform(post("/api/v1/sales-orders/"+second+"/allocate").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ALLOCATED")).andExpect(jsonPath("$.lines[0].allocatedQuantity").value(50.0));assertBalance(130,130);assertEquals(0,db.queryForObject("SELECT count(*) FROM inventory_reservations r LEFT JOIN sales_allocations a ON a.tenant_id=r.tenant_id AND a.inventory_reservation_id=r.id WHERE r.reference_type='SALES_ORDER_LINE' AND a.id IS NULL",Integer.class));}
 @Test void cancellationReleasesEveryReservationWithoutLedgerMovement()throws Exception{stock("stock",10);int ledger=count("inventory_ledger_entries");UUID o=ready(activeCustomer(),"10");mvc.perform(post("/api/v1/sales-orders/"+o+"/allocate").with(token())).andExpect(status().isOk());mvc.perform(post("/api/v1/sales-orders/"+o+"/cancel").with(token()).contentType("application/json").content("{\"version\":3,\"reason\":\"Customer request\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("CANCELLED"));assertBalance(10,0);assertEquals(ledger,count("inventory_ledger_entries"));assertEquals(0,db.queryForObject("SELECT count(*) FROM inventory_reservations WHERE status='ACTIVE' AND reference_type='SALES_ORDER_LINE'",Integer.class));}
 @Test void twoConcurrentOrdersNeverOverAllocate()throws Exception{stock("ten",10);UUID c=activeCustomer(),a=ready(c,"10"),b=ready(c,"10");ExecutorService p=Executors.newFixedThreadPool(2);try{CountDownLatch go=new CountDownLatch(1);Future<Integer>x=p.submit(()->{go.await();return allocateStatus(a);}),y=p.submit(()->{go.await();return allocateStatus(b);});go.countDown();assertEquals(200,x.get());assertEquals(200,y.get());assertBalance(10,10);assertEquals(10,db.queryForObject("SELECT COALESCE(sum(allocated_quantity),0) FROM sales_order_lines",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM sales_allocations a JOIN inventory_reservations r ON r.id=a.inventory_reservation_id WHERE a.status='ACTIVE' AND r.status<>'ACTIVE'",Integer.class));}finally{p.shutdownNow();}}
 @Test void fefoAndSerializedCandidatesAreDeterministic()throws Exception{db.update("UPDATE catalog_product_variants SET tracking_mode='LOT',expiration_required=true WHERE id=?",V);UUID late=lot("LATE",30),early=lot("EARLY",5);balance(L,late,null,5);balance(L,early,null,5);UUID o=ready(activeCustomer(),"6");mvc.perform(post("/api/v1/sales-orders/"+o+"/allocate").with(token())).andExpect(status().isOk());UUID first=db.queryForObject("SELECT x.lot_id FROM sales_allocations a JOIN inventory_reservation_allocations x ON x.reservation_id=a.inventory_reservation_id WHERE a.sales_order_id=? ORDER BY a.created_at LIMIT 1",UUID.class,o);assertEquals(early,first);assertEquals(5,db.queryForObject("SELECT reserved_quantity FROM inventory_balances WHERE lot_id=?",Integer.class,early));}
 @Test void zeroAtpIsBackorderedAndCrossTenantObjectsAreHidden()throws Exception{UUID c=activeCustomer(),o=ready(c,"4");mvc.perform(post("/api/v1/sales-orders/"+o+"/allocate").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("PARTIALLY_ALLOCATED")).andExpect(jsonPath("$.lines[0].allocatedQuantity").value(0.0)).andExpect(jsonPath("$.lines[0].backorderedQuantity").value(4.0));UUID other=UUID.randomUUID();mvc.perform(get("/api/v1/sales-orders/"+o).with(jwt().jwt(j->j.subject("seller").claim("tenant_id",other.toString())))).andExpect(status().isForbidden());mvc.perform(post("/api/v1/sales-orders").with(token()).contentType("application/json").content("{\"customerId\":\""+UUID.randomUUID()+"\",\"warehouseId\":\""+W+"\"}")).andExpect(status().isNotFound());}
 @Test void authorizationPaginationSortingAndOpenApiAreCovered()throws Exception{mvc.perform(get("/api/v1/customers")).andExpect(status().isUnauthorized());mvc.perform(get("/api/v1/sales-orders?size=101").with(token())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_PAGINATION"));mvc.perform(get("/api/v1/customers?sort=tenantId").with(token())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_SORT"));mvc.perform(get("/v3/api-docs").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.paths['/api/v1/customers']").exists()).andExpect(jsonPath("$.paths['/api/v1/sales-orders/{id}/allocate']").exists());}
 @Test void serializedAllocationUsesEachSerialExactlyOnce()throws Exception{db.update("UPDATE catalog_product_variants SET tracking_mode='SERIAL' WHERE id=?",V);UUID s1=UUID.randomUUID(),s2=UUID.randomUUID();for(var x:List.of(Map.entry(s1,"SN-001"),Map.entry(s2,"SN-002"))){db.update("INSERT INTO inventory_serials(id,tenant_id,variant_id,serial_number,normalized_serial_number,status,created_at,updated_at,version)VALUES(?,?,?,?,?,'ACTIVE',now(),now(),0)",x.getKey(),T,V,x.getValue(),x.getValue());balance(L,null,x.getKey(),1);}UUID o=ready(activeCustomer(),"2");mvc.perform(post("/api/v1/sales-orders/"+o+"/allocate").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ALLOCATED"));assertEquals(2,db.queryForObject("SELECT count(DISTINCT x.serial_id) FROM sales_allocations a JOIN inventory_reservation_allocations x ON x.reservation_id=a.inventory_reservation_id WHERE a.sales_order_id=?",Integer.class,o));assertEquals(2,db.queryForObject("SELECT sum(reserved_quantity) FROM inventory_balances WHERE serial_id IS NOT NULL",Integer.class));}
 @Test void customerCountersAreUniqueUnderConcurrency()throws Exception{ExecutorService p=Executors.newFixedThreadPool(8);try{List<Future<UUID>>cs=new ArrayList<>();for(int i=0;i<12;i++)cs.add(p.submit(()->customer(false)));for(var f:cs)f.get();assertEquals(12,db.queryForObject("SELECT count(DISTINCT customer_number) FROM customers",Integer.class));}finally{p.shutdownNow();}}
 private UUID activeCustomer()throws Exception{UUID c=customer(false);activate(c);return c;}private UUID customer(boolean ignored)throws Exception{return id(mvc.perform(post("/api/v1/customers").with(token()).contentType("application/json").content(customerJson(0))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}private void activate(UUID c)throws Exception{mvc.perform(post("/api/v1/customers/"+c+"/activate").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk());}private UUID order(UUID c)throws Exception{return id(mvc.perform(post("/api/v1/sales-orders").with(token()).contentType("application/json").content("{\"customerId\":\""+c+"\",\"warehouseId\":\""+W+"\",\"customerReference\":\"WEB-1\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.orderNumber").value(org.hamcrest.Matchers.matchesPattern("SO-[0-9]{4}-[0-9]{6}"))).andReturn().getResponse().getContentAsString());}private UUID ready(UUID c,String q)throws Exception{UUID o=order(c);line(o,q,"10");mvc.perform(post("/api/v1/sales-orders/"+o+"/confirm").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isOk());return o;}private void line(UUID o,String q,String p)throws Exception{mvc.perform(post("/api/v1/sales-orders/"+o+"/lines").with(token()).contentType("application/json").content(lineJson(q,p))).andExpect(status().isOk());}private String lineJson(String q,String p){return "{\"variantId\":\""+V+"\",\"quantity\":\""+q+"\",\"unitPrice\":\""+p+"\"}";}private String customerJson(long v){return "{\"name\":\"Acme GmbH\",\"currency\":\"EUR\",\"shippingAddress\":\"Main Street 1, Berlin, DE\",\"version\":"+v+"}";}private void stock(String key,int q)throws Exception{mvc.perform(post("/api/v1/inventory/adjustments").with(token()).header("Idempotency-Key",key).contentType("application/json").content("{\"variantId\":\""+V+"\",\"warehouseId\":\""+W+"\",\"locationId\":\""+L+"\",\"quantityDelta\":\""+q+"\",\"reason\":\"MANUAL_CORRECTION\"}")).andExpect(status().isOk());}private void assertBalance(int onHand,int reserved){assertEquals(onHand,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances WHERE lot_id IS NULL AND serial_id IS NULL",Integer.class));assertEquals(reserved,db.queryForObject("SELECT reserved_quantity FROM inventory_balances WHERE lot_id IS NULL AND serial_id IS NULL",Integer.class));}private int allocateStatus(UUID o)throws Exception{return mvc.perform(post("/api/v1/sales-orders/"+o+"/allocate").with(token())).andReturn().getResponse().getStatus();}private UUID lot(String n,int days){UUID id=UUID.randomUUID();db.update("INSERT INTO inventory_lots(id,tenant_id,variant_id,lot_number,normalized_lot_number,expires_on,status,created_at,updated_at,version)VALUES(?,?,?,?,?,current_date+?,'ACTIVE',now(),now(),0)",id,T,V,n,n,days);return id;}private void balance(UUID location,UUID lot,UUID serial,int q){db.update("INSERT INTO inventory_balances(id,tenant_id,variant_id,warehouse_id,location_id,lot_id,serial_id,on_hand_quantity,reserved_quantity,unit_code,updated_at,version)VALUES(?,?,?,?,?,?,?,?,0,'EA',now(),0)",UUID.randomUUID(),T,V,W,location,lot,serial,q);}private int count(String t){return db.queryForObject("SELECT count(*) FROM "+t,Integer.class);}private UUID id(String json){return UUID.fromString(json.replaceAll(".*\"id\":\"([^\"]+)\".*","$1"));}private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("seller").claim("tenant_id",T.toString()));}
}
